<?php
namespace App\Actions\ServiceOrders;use App\Enums\ServiceOrderStatus;use App\Models\{ServiceOrder,Product,ServiceOrderItem};use DomainException;use Illuminate\Support\Facades\DB;
class AddServiceOrderItem{public function execute(ServiceOrder $o,?Product $p,array $d,bool $recalculate=true):ServiceOrderItem{if(in_array((string)$o->status,[ServiceOrderStatus::COMPLETED,ServiceOrderStatus::CANCELLED],true))throw new DomainException('Cannot add item to closed order');$name=trim((string)($d['name']??($p?$p->name:'')));if($name==='')throw new DomainException('Product or service name is required');return DB::transaction(function()use($o,$p,$d,$recalculate,$name){$q=(float)($d['quantity']??1);$price=(float)($d['unit_price']??($p?$p->selling_price:0));$discount=(float)($d['discount_amount']??0);$i=$o->items()->create(['product_id'=>$p?$p->id:null,'item_type'=>$d['item_type'],'name'=>$name,'sku'=>$p?$p->sku:null,'quantity'=>$q,'unit_price'=>$price,'cost_price'=>$p?$p->cost_price:($d['cost_price']??0),'discount_amount'=>$discount,'total_amount'=>max(0,$q*$price-$discount),'note'=>$d['note']??null]);if($recalculate)app(RecalculateServiceOrderTotals::class)->execute($o);return $i;});}}
